Write a pytest test verifying that a failed transaction is rolled back and leaves the table unchanged.

import sqlite3

def transfer_amount(conn, src, dst, amount):
    try:
        conn.execute('UPDATE accounts SET balance = balance - ? WHERE name = ?', (amount, src))
        conn.execute('UPDATE accounts SET balance = balance + ? WHERE name = ?', (amount, dst))
        if amount <= 0:
            raise ValueError('invalid amount')
        conn.commit()
    except Exception:
        conn.rollback()
        raise

Write a pytest test for a small repository class wrapping sqlite3, covering full CRUD lifecycle.

class UserRepo:
    def __init__(self, conn):
        self.conn = conn
    def create(self, name):
        cur = self.conn.execute('INSERT INTO users (name) VALUES (?)', (name,))
        self.conn.commit()
        return cur.lastrowid
    def get(self, user_id):
        row = self.conn.execute('SELECT id, name FROM users WHERE id = ?', (user_id,)).fetchone()
        return {'id': row[0], 'name': row[1]} if row else None
    def delete(self, user_id):
        self.conn.execute('DELETE FROM users WHERE id = ?', (user_id,))
        self.conn.commit()

