Write a pytest test that uses a fixture to ensure the connection is closed after each test, asserting the closed state via a flag.

import sqlite3

class Connection:
    def __init__(self, dsn):
        self.conn = sqlite3.connect(dsn)
        self.closed = False
    def close(self):
        self.conn.close()
        self.closed = True

