import pytest
from connection import Connection

@pytest.fixture
def db_conn():
    conn = Connection(':memory:')
    yield conn
    conn.close()

def test_connection_is_open_by_default(db_conn):
    assert db_conn.closed is False

def test_connection_can_query(db_conn):
    row = db_conn.conn.execute('SELECT 1 + 1').fetchone()
    assert row[0] == 2

def test_fixture_closes_after_test():
    conn = Connection(':memory:')
    conn.close()
    assert conn.closed is True

import sqlite3
import pytest
from configs import save_config, load_config

@pytest.fixture
def conn():
    conn = sqlite3.connect(':memory:')
    conn.execute('CREATE TABLE configs (key TEXT PRIMARY KEY, data TEXT)')
    return conn

def test_json_blob_round_trip(conn):
    payload = {'workers': 4, 'debug': False, 'tags': ['a', 'b']}
    save_config(conn, 'app', payload)
    assert load_config(conn, 'app') == payload

def test_load_missing_key(conn):
    assert load_config(conn, 'nope') is None

def test_overwrite_config(conn):
    save_config(conn, 'app', {'v': 1})
    save_config(conn, 'app', {'v': 2})
    assert load_config(conn, 'app') == {'v': 2}

