Write a pytest test for a migration function that adds a column and backfills it, verifying old rows get the default value.

import sqlite3

def migrate_add_status(conn):
    columns = {r[1] for r in conn.execute('PRAGMA table_info(items)')}
    if 'status' not in columns:
        conn.execute("ALTER TABLE items ADD COLUMN status TEXT DEFAULT 'active'")
        conn.commit()

Write a pytest test for a connection context manager that commits on success and rolls back when the block raises.

import sqlite3
from contextlib import contextmanager

@contextmanager
def transaction(conn):
    try:
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise

